B.anT=s(["Yogur griego \u2192 yogur natural o 100 g de queso fresco batido.","Leche entera \u2192 de soja o semidesnatada."],t.s)
B.b_z=new A.aQ(B.H,B.are,null,"Liso y cremoso, sin grumos de prote\xedna.",B.ayo,B.alg,B.anT,"Mejor al momento.",null,B.B)
B.amx=s(["Bol"],t.s)
B.asV=s(["La granola, justo al servir: si no, se ablanda.","El yogur griego tiene m\xe1s calor\xedas y cremosidad; el de prote\xednas, m\xe1s prote\xedna."],t.s)
B.am6=s(["Granola \u2192 copos de avena con nueces y miel."],t.s)
